class TestRestartOrchestration:
    """Restart logic: cooldown, max attempts, backoff."""

    @pytest.mark.asyncio
    @patch("swarm_v2.core.self_healing_infra.subprocess.Popen")
    async def test_restart_success(self, mock_popen, monitor: ServiceMonitor):
        """Restart launches the process and resets attempts on success."""
        mock_proc = MagicMock()
        mock_proc.poll.return_value = None  # Process is running
        mock_popen.return_value = mock_proc

        result = await monitor._restart_service()
        assert result is True
        assert monitor.restart_attempts == 1
        mock_popen.assert_called_once()

    @pytest.mark.asyncio
    @patch("swarm_v2.core.self_healing_infra.subprocess.Popen")
    async def test_restart_failure_subprocess_error(self, mock_popen, monitor: ServiceMonitor):
        """Subprocess failure returns False and increments attempts."""
        mock_popen.side_effect = subprocess.SubprocessError("Failed to launch")

        result = await monitor._restart_service()
        assert result is False
        assert monitor.restart_attempts == 1

    @pytest.mark.asyncio
    @patch("swarm_v2.core.self_healing_infra.subprocess.Popen")
    async def test_restart_failure_oserror(self, mock_popen, monitor: ServiceMonitor):
        """OSError returns False and increments attempts."""
        mock_popen.side_effect = OSError("Permission denied")

        result = await monitor._restart_service()
        assert result is False
        assert monitor.restart_attempts == 1

    @pytest.mark.asyncio
    @patch("swarm_v2.core.self_healing_infra.subprocess.Popen")
    async def test_restart_max_attempts(self, mock_popen, monitor: ServiceMonitor):
        """Restart stops after max_restart_attempts."""
        mock_popen.side_effect = subprocess.SubprocessError("Failed")

        for _ in range(monitor.config.max_restart_attempts + 2):
            await monitor._restart_service()

        assert monitor.restart_attempts == monitor.config.max_restart_attempts
        # After max attempts, further restarts are blocked
        result = await monitor._restart_service()
        assert result is False

    @pytest.mark.asyncio
    @patch("swarm_v2.core.self_healing_infra.subprocess.Popen")
    async def test_restart_cooldown(self, mock_popen, monitor: ServiceMonitor):
        """Restart respects cooldown period."""
        monitor.last_restart_attempt = time.time() - 1  # 1 second ago
        monitor.config.restart_cooldown = 10.0

        result = await monitor._restart_service()
        assert result is False
        mock_popen.assert_not_called()

    @pytest.mark.asyncio
    @patch("swarm_v2.core.self_healing_infra.subprocess.Popen")
    async def test_restart_after_cooldown_expired(self, mock_popen, monitor: ServiceMonitor):
        """Restart proceeds after cooldown has elapsed."""
        monitor.last_restart_attempt = time.time() - 20  # 20 seconds ago
        monitor.config.restart_cooldown = 10.0
        mock_proc = MagicMock()
        mock_proc.poll.return_value = None
        mock_popen.return_value = mock_proc

        result = await monitor._restart_service()
        assert result is True
        mock_popen.assert_called_once()

    @pytest.mark.asyncio
    @patch("swarm_v2.core.self_healing_infra.subprocess.Popen")
    async def test_restart_backoff(self, mock_popen, monitor: ServiceMonitor):
        """Backoff factor increases wait time between attempts."""
        monitor.config.max_restart_attempts = 5
        mock_popen.side_effect = subprocess.SubprocessError("Failed")

        with patch("asyncio.sleep", new=AsyncMock()) as mock_sleep:
            await monitor._restart_service()
            await monitor._restart_service()
            await monitor._restart_service()

        # Verify sleep was called with increasing backoff durations
        calls = [call.args[0] for call in mock_sleep.call_args_list]
        assert len(calls) == 3
        assert calls[0] < calls[1] < calls[2]

    @pytest.mark.asyncio
    @patch("swarm_v2.core.self_healing_infra.subprocess.Popen")
    async def test_restart_uses_process_cmd(self, mock_popen, monitor: ServiceMonitor):
        """Restart uses the configured process command."""
        mock_proc = MagicMock()
        mock_proc.poll.return_value = None
        mock_popen.return_value = mock_proc

        await monitor._restart_service()
        args, kwargs = mock_popen.call_args
        assert args[0] == monitor.config.process_cmd
        assert kwargs.get("env") == monitor.config.env_vars
        assert kwargs.get("cwd") == monitor.config.working_dir

    @pytest.mark.asyncio
    @patch("swarm_v2.core.self_healing_infra.subprocess.Popen")
    async def test_restart_no_process_cmd(self, mock_popen, monitor: ServiceMonitor):
        """Restart returns False when no process command is configured."""
        monitor.config.process_cmd = []
        result = await monitor._restart_service()
        assert result is False
        mock_popen.assert_not_called()


