class TestRaceConditionResistance:
    """Concurrent operations must not corrupt state."""

    @pytest.mark.asyncio
    async def test_concurrent_health_checks(self, monitor: ServiceMonitor):
        """Multiple concurrent health checks do not raise."""
        with patch("urllib.request.urlopen") as mock_urlopen:
            mock_response = MagicMock()
            mock_response.status = 200
            mock_response.read.return_value = b'{"status": "ok"}'
            mock_urlopen.return_value.__enter__.return_value = mock_response

            results = await asyncio.gather(
                *[monitor._check_health() for _ in range(10)]
            )
            assert all(r is None for r in results)
            assert monitor.status == ServiceStatus.HEALTHY

    @pytest.mark.asyncio
    @patch("swarm_v2.core.self_healing_infra.subprocess.Popen")
    async def test_concurrent_restarts(self, mock_popen, monitor: ServiceMonitor):
        """Concurrent restarts are serialized."""
        mock_proc = MagicMock()
        mock_proc.poll.return_value = None
        mock_popen.return_value = mock_proc

        results = await asyncio.gather(
            *[monitor._restart_service() for _ in range(5)]
        )
        # Only the first should succeed; others blocked by cooldown
        assert results.count(True) == 1
        assert results.count(False) == 4

    @pytest.mark.asyncio
    async def test_concurrent_start_stop(self, monitor: ServiceMonitor):
        """Concurrent start/stop does not leave monitor in invalid state."""
        await asyncio.gather(monitor.start(), monitor.stop())
        assert monitor.is_running in (True, False)  # Either is valid
        await monitor.stop()  # Ensure clean state

    @pytest.mark.asyncio
    async def test_status_update_race(self, monitor: ServiceMonitor):
        """Status updates from concurrent checks are consistent."""
        with patch("urllib.request.urlopen") as mock_urlopen:
            mock_response = MagicMock()
            mock_response.status = 200
            mock_response.read.return_value = b'{"status": "ok"}'
            mock_urlopen.return_value.__enter__.return_value = mock_response

            await asyncio.gather(
                *[monitor._check_health() for _ in range(20)]
            )
            assert monitor.status == ServiceStatus.HEALTHY


