    async def test_process_detection(self, mock_process_cls, monitor: ServiceMonitor):
        """Process is detected by name."""
        mock_proc = MagicMock()
        mock_proc.name.return_value = "api_gateway"
        mock_process_cls.return_value = mock_proc

        found = monitor._find_process()
        assert found is not None
        mock_process_cls.assert_called_once()

    @pytest.mark.asyncio
    @patch("psutil.Process")
    async def test_process_not_found(self, mock_process_cls, monitor: ServiceMonitor):
        """Missing process returns None."""
        mock_process_cls.side_effect = psutil.NoSuchProcess(1234)
        found = monitor._find_process()
        assert found is None

    @pytest.mark.asyncio
    @patch("psutil.Process")
    async def test_process_access_denied(self, mock_process_cls, monitor: ServiceMonitor):
        """AccessDenied is handled gracefully."""
        mock_process_cls.side_effect = psutil.AccessDenied(1234)
        found = monitor._find_process()
        assert found is None

    @pytest.mark.asyncio
    @patch("psutil.Process")
    async def test_process_zombie(self, mock_process_cls, monitor: ServiceMonitor):
        """Zombie process is detected."""
        mock_proc = MagicMock()
        mock_proc.name.return_value = "api_gateway"
        mock_proc.status.return_value = psutil.STATUS_ZOMBIE
        mock_process_cls.return_value = mock_proc

        found = monitor._find_process()
        assert found is not None
        assert found.status() == psutil.STATUS_ZOMBIE


