class TestSignalHandling:
    """Graceful shutdown on signals."""

    @pytest.mark.asyncio
    async def test_sigterm_handler(self, monitor: ServiceMonitor):
        """SIGTERM triggers graceful stop."""
        with patch.object(monitor, "stop", new=AsyncMock()) as mock_stop:
            monitor._handle_signal(signal.SIGTERM, None)
            await asyncio.sleep(0.1)
            mock_stop.assert_called_once()

    @pytest.mark.asyncio
    async def test_sigint_handler(self, monitor: ServiceMonitor):
        """SIGINT triggers graceful stop."""
        with patch.object(monitor, "stop", new=AsyncMock()) as mock_stop:
            monitor._handle_signal(signal.SIGINT, None)
            await asyncio.sleep(0.1)
            mock_stop.assert_called_once()


