# Performance & Stress Tests
# ============================================================================

class TestPerformance:
    """Performance characteristics under load."""

    @pytest.mark.asyncio
    async def test_health_check_latency(self, monitor: ServiceMonitor):
        """Health check completes within reasonable time."""
        with patch("urllib.request.urlopen") as mock_urlopen:
            mock_response = MagicMock()
            mock_response.status = 200
            mock_response.read.return_value = b'{"status": "ok"}'
            mock_urlopen.return_value.__enter__.return_value = mock_response

            start = time.perf_counter()
            await monitor._check_health()
            elapsed = time.perf_counter() - start
            assert elapsed < 1.0  # Should be fast with mocked I/O

    @pytest.mark.asyncio
    async def test_many_sequential_health_checks(self, monitor: ServiceMonitor):
        """100 sequential health checks complete without error."""
        with patch("urllib.request.urlopen") as mock_urlopen:
            mock_response = MagicMock()
            mock_response.status = 200
            mock_response.read.return_value = b'{"status": "ok"}'
            mock_urlopen.return_value.__enter__.return_value = mock_response

            for _ in range(100):
                await monitor._check_health()
            assert monitor.status == ServiceStatus.HEALTHY


